/**
 * @name Path traversal vulnerability
 * @description User input flows into file operations without proper sanitization
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // File open operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    // os.path operations
    exists(DataFlow::CallCfgNode call |
      (call = API::moduleImport("os").getMember("path").getMember(["join", "abspath", "realpath", "normpath"]).getACall() or
       call = API::moduleImport("os").getMember(["remove", "unlink", "rmdir", "mkdir", "makedirs", "rename", "stat", "lstat", "chmod", "chown", "utime", "access"]).getACall()) and
      sink = call.getArg(0)
    ) or
    // pathlib operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    ) or
    // shutil operations
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("shutil").getMember(["copy", "copy2", "copytree", "move", "rmtree"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal vulnerability from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description File path operations that could allow directory traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // File opening operations
      call = API::moduleImport("os").getMember(["open", "chdir", "remove", "unlink", "rename", "stat"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("builtins").getMember("open").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("shutil").getMember(["copy", "move", "rmtree"]).getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pathlib").getMember("Path").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      // File system module
      call = API::moduleImport("os").getMember("path").getMember(["join", "abspath", "normpath"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential path traversal vulnerability from $@.", source.getNode(), "user input"
